/**
 * @name Trace flow to eval in optimize/_nonlin.py
 * @description Traces flow from function parameters to eval in scipy/optimize/_nonlin.py
 * @kind path-problem
 * @problem.severity error
 * @id py/scipy-optimize-eval-trace
 * @tags security
 *       external/cwe/cwe-095
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

module OptimizeEvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(Call call |
      call.getFunc().(Name).getId() = "eval" or
      call.getFunc().(Name).getId() = "exec" |
      sink.asExpr() = call.getArg(0)
    )
    and sink.getLocation().getFile().getShortName() = "_nonlin.py"
  }
}

module OptimizeEvalFlow = TaintTracking::Global<OptimizeEvalConfig>;
import OptimizeEvalFlow::PathGraph

from OptimizeEvalFlow::PathNode source, OptimizeEvalFlow::PathNode sink
where OptimizeEvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection in optimize/_nonlin.py from parameter $@.", source.getNode(), source.getNode().toString()

/**
 * @name Scipy Datasets Pickle Source Inspection
 * @description Trace the source of data passed to pickle.load in scipy.datasets
 * @kind path-problem
 * @problem.severity error
 * @id py/scipy-datasets-pickle-source
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PickleConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Look for parameters of fetch functions or file opens
    exists(DataFlow::ParameterNode p |
      p.getScope().getEnclosingModule().getName().matches("scipy.datasets%") and
      source = p
    )
    or
    source = API::moduleImport("pooch").getMember("retrieve").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember("load").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleFlow = TaintTracking::Global<PickleConfig>;
import PickleFlow::PathGraph

from PickleFlow::PathNode source, PickleFlow::PathNode sink
where PickleFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Pickle load from $@", source.getNode(), "source"

